head.script:
scwin.onpageload = function() {
    dataList1.insertRow();
    dataList2.insertRow();
    var row = dataList1.getRowJSON(0);
    var json = [];
    for (var i = 0; i < 2; i++) {
        var tmp = {};
        for (var item in row) {
            if (item == "rowStatus") continue;
            else if (item == "col1" ||
                item == "col2" ||
                item == "col3"
            ) tmp[item] = "0"
            else tmp[item] = item + "_" + i;
        }
        json.push(tmp);
    }
    dataList1.setJSON(json);
    row = dataList2.getRowJSON(0);
    json = [];
    for (var i = 0; i < 2; i++) {
        var tmp = {};
        for (var item in row) {
            if (item == "rowStatus") continue;
            else if (item == "col1" ||
                item == "col2" ||
                item == "col3"
            ) tmp[item] = 0
            else tmp[item] = item + "_" + i;
        }
        json.push(tmp);
    }
    // dataList2.setJSON([
    //     {"col1":"col1","col2":"col2","col3":"col3","col4":"col4"}
    // ]);
    dataList2.setJSON(json);
};
scwin.onpageunload = function() {};
scwin.gridView1_onviewchange = function(info) {
    debugger;
    console.log(info);
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#G_gridView1__col2', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#G_gridView1__col3', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById($p.id + 'wq_uuid_3_itemTable_main').getElementsByTagName('tr')[1].innerText == "하하가가나가나다라하";
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.setVal1 = function() {
    WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1__col2').value = '-';
}
scwin.setVal2 = function() {
    WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1__col3').value = '+';
}
scwin.setVal3 = function() {
    WebSquare.wUnit.getDomById('G_'+$p.id+'gridView2__col2').value = '-';
}
scwin.setVal4 = function() {
    WebSquare.wUnit.getDomById('G_'+$p.id+'gridView2__col3').value = '+';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gridView1_cell_0_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setVal1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gridView1_cell_0_2')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setVal2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gridView2_cell_0_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setVal3()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView2_cell_0_3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gridView2_cell_0_2')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setVal4()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView2_cell_0_3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView2_cell_0_4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView1_cell_0_1').innerText == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView1_cell_0_2').innerText == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView2_cell_0_1').innerText == ''", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView2_cell_0_2').innerText == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
